style.css:
@-moz-document url-prefix("https://admin192c.acellus.com/student/2/") {
/* Set the entire page background to light pink */
    body {
        background-color: #ffe4e1 !important; /* Light pink */
    }

    /* Set containers, classes, and main content background to cream */
    .content, .class-container, .dashboard-panel, .card, .widget {
        background-color: #fffdd0 !important; /* Cream */
        border-radius: 8px; /* Smooth corners */
        padding: 15px; /* Add spacing inside elements */
        box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.1); /* Subtle shadow */
    }

    /* Preserve visibility of buttons and widgets */
    button, .widget, .class-button {
        background-color: inherit !important;
        color: inherit !important;
        border: none !important;
    }

    /* Adjust text colors for readability */
    p, span, h1, h2, h3, h4, h5, h6 {
        color: #333 !important; /* Dark gray */
    }

    /* Optional hover effect for buttons */
    button:hover, .class-button:hover {
        background-color: #ffc0cb !important; /* Darker pink */
    }
}
